import { StoryProgress, Card } from "march/ui"

// beş saniyelik geri sayım: beş parça, biri bitince sıradaki başlar
export function Countdown() {
  let $i = 0
  return <Card m:theme="night">
    <StoryProgress count={5} index={$i} duration={1000} color="brand-orange" onDone={() => { if ($i < 4) $i++ }} />
    <span sx={{ text: ["2xl", "bold"] }}>{5 - $i}</span>
  </Card>
}

import { StoryProgress } from "march/ui"

// StoryProgress'in özellikleri: count, index, duration, paused, run, onDone, label, color, class
export function StoryProgressLab() {
  return <div sx={{ flex: "col", gap: 2 }}>
    <StoryProgress class="lab-sp" count={4} index={2} duration={3000} paused run="a" onDone={() => {}}
      label={(i: number, n: number) => `Hikâye ${i + 1} / ${n}`} color="brand-green" />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { StoryProgressLab } from "./StoryProgressLab.tsx"

// StoryProgressLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ince bölümlü çubuk, class köke eklenir", () => {
  const s = renderTest(() => <StoryProgressLab />)
  expect(s.get(".lab-sp")?.classList.contains("m-story-progress")).toBe(true)
})

test("label şimdiki hikâyeyi okur", () => {
  const s = renderTest(() => <StoryProgressLab />)
  expect(s.get(".lab-sp")?.outerHTML).toContain("Hikâye 3 / 4")
})
